{
  "passageId": "audio-perceptual-coding",
  "items": [
    {
      "slot": 1,
      "stem": "윗글의 내용에 대한 이해로 적절하지 않은 것은?",
      "stemPolarity": "SELECT_INCORRECT",
      "choices": [
        {
          "number": 1,
          "text": "축음기는 나팔에 들려준 소리가 나팔의 진동으로 바뀌면 바늘이 그 진동 형태를 따라 판에 홈을 만들어 소리를 저장한다."
        },
        {
          "number": 2,
          "text": "오디오 파일은 저장하거나 네트워크로 전송하기에 데이터 양이 많으므로 공간을 절약하고 전송을 가능하게 하려면 압축이 필요하다."
        },
        {
          "number": 3,
          "text": "초기 녹음기 이후에 등장한 매체에서는 소리를 아날로그 형태로 기록하는 방식이 사용되지 않았다."
        },
        {
          "number": 4,
          "text": "1,000 Hz부터 10,000 Hz 사이에서 아주 작은 소리도 들을 수 있는 것과 달리 100 Hz 이하에서는 훨씬 큰 소리여야 들을 수 있다."
        },
        {
          "number": 5,
          "text": "일반적으로 각 소리 크기에 16비트를 할당할 때 소리 크기에 따라 16자리 이진수의 값을 달리하여 소리 크기를 구분한다."
        }
      ],
      "answer": 3
    },
    {
      "slot": 2,
      "stem": "윗글의 내용에 대한 이해로 적절한 것은?",
      "stemPolarity": "SELECT_CORRECT",
      "choices": [
        {
          "number": 1,
          "text": "각 소리 크기에 할당되는 비트의 개수가 늘어날수록 디지털 신호로 저장된 소리는 아날로그 원음에서 멀어진다."
        },
        {
          "number": 2,
          "text": "지각부호화는 청각 특성에 따라 청각이 민감하게 감지하는 소리를 제거하는 방식으로 오디오 신호를 압축한다."
        },
        {
          "number": 3,
          "text": "지각부호화는 신호를 주파수에 따라 임계대역으로 나눈 다음 각 대역의 최소가청강도와 차폐음을 고려하여 차폐 문턱값을 구한다."
        },
        {
          "number": 4,
          "text": "두 소리의 주파수가 가까울 때 차폐가 쉽게 일어나며 주파수가 충분히 떨어져 있을 때에도 차폐가 일어난다."
        },
        {
          "number": 5,
          "text": "차폐음의 주파수를 기준으로 정해지는 임계대역의 폭은 고음의 경우와 저음의 경우를 비교하면 같은 수준이다."
        }
      ],
      "answer": 3
    },
    {
      "slot": 3,
      "stem": "차폐 문턱값에 대한 이해로 적절한 것은?",
      "stemPolarity": "SELECT_CORRECT",
      "choices": [
        {
          "number": 1,
          "text": "차폐 문턱값은 최소가청강도와 마찬가지로 차폐를 고려하여 정하는 소리 크기의 최소 감지 기준이다."
        },
        {
          "number": 2,
          "text": "차폐 문턱값보다 큰 소리는 그 크기와 문턱값의 차이가 클수록 지각부호화에서 더 적은 비트를 할당받는다."
        },
        {
          "number": 3,
          "text": "차폐 문턱값보다 작은 소리들은 실제 청각으로 감지할 수 없으므로 지각부호화에서 제거하는 대상이 된다."
        },
        {
          "number": 4,
          "text": "차폐 문턱값은 차폐를 고려했을 때 실제 청각이 감지할 수 있는 소리의 주파수가 갖는 최솟값을 뜻한다."
        },
        {
          "number": 5,
          "text": "각 임계대역의 차폐 문턱값을 구할 때 최소가청강도는 고려하지만 차폐를 일으키는 큰 소리는 고려하지 않는다."
        }
      ],
      "answer": 3
    }
  ]
}

